//! Reading a table whose `DATA` and `WEIGHT_SPECTRUM` columns are stored with
//! the Dysco storage manager. The fixture is generated by
//! `tests/data/make_dysco_fixture.py` with python-casacore, which also stores
//! its own decoding of the compressed columns in `DATA_DECODED` and
//! `WEIGHT_DECODED` (with `StandardStMan`), and the uncompressed input in
//! `DATA_ORIG`.

#![cfg(feature = "dysco")]

use rubbl_casatables::{Complex, Table, TableOpenMode};
use std::path::PathBuf;

fn fixture() -> Table {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/data/dysco.tab");
    Table::open(path, TableOpenMode::Read).unwrap()
}

#[test]
fn dysco_data_matches_casacore_decoding() {
    let mut t = fixture();
    assert_eq!(t.n_rows(), 18);

    let mut sum_err2 = 0.0f64;
    let mut sum_orig2 = 0.0f64;

    for row in 0..t.n_rows() {
        let data: Vec<Complex<f32>> = t.get_cell_as_vec("DATA", row).unwrap();
        let decoded: Vec<Complex<f32>> = t.get_cell_as_vec("DATA_DECODED", row).unwrap();
        let orig: Vec<Complex<f32>> = t.get_cell_as_vec("DATA_ORIG", row).unwrap();
        assert_eq!(data.len(), 32);
        // Bit-identical to what (python-)casacore's DyscoStMan decodes.
        assert_eq!(data, decoded, "row {}", row);

        for (d, o) in data.iter().zip(orig.iter()) {
            sum_err2 += (d - o).norm_sqr() as f64;
            sum_orig2 += o.norm_sqr() as f64;
        }
    }

    // And close to the uncompressed input (10-bit data, AF normalization).
    let rel_rms = (sum_err2 / sum_orig2).sqrt();
    assert!(
        rel_rms > 0.0 && rel_rms < 0.05,
        "relative RMS error {}",
        rel_rms
    );
}

#[test]
fn dysco_weights_match_casacore_decoding() {
    let mut t = fixture();

    for row in 0..t.n_rows() {
        let w: Vec<f32> = t.get_cell_as_vec("WEIGHT_SPECTRUM", row).unwrap();
        let decoded: Vec<f32> = t.get_cell_as_vec("WEIGHT_DECODED", row).unwrap();
        assert_eq!(w, decoded, "row {}", row);
    }
}
